CREATE FUNCTION public.public_app_captions() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce((SELECT jsonb_object_agg(e.key,jsonb_build_object('name',e.value->>'name','description',e.value->>'description')) FROM public.cde_selected c CROSS JOIN LATERAL jsonb_each(c.variant_key::jsonb->'apps') e WHERE c.group_key='app_tile' AND c.is_primary),'{}'::jsonb) $$; REVOKE ALL ON FUNCTION public.public_app_captions() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.public_app_captions() TO anon,authenticated;
CREATE FUNCTION public.spend_project_allowed(_project uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.projects p WHERE p.id=_project AND p.status='active' AND (public.spend_role()='finance' OR p.created_by=auth.uid() OR EXISTS(SELECT 1 FROM public.pm_projects m JOIN public.pm_members u ON u.project_id=m.id WHERE m.erp_project_id=p.id AND u.user_id=auth.uid() AND m.status NOT IN ('concluded','cancelled')))) $$; REVOKE ALL ON FUNCTION public.spend_project_allowed(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.spend_project_allowed(uuid) TO authenticated;
DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.spend_workspace()'::regprocedure) INTO d; d:=replace(d,'p.status=''active'' AND (r=''finance'' OR p.created_by=auth.uid())','public.spend_project_allowed(p.id)'); EXECUTE d; SELECT pg_get_functiondef('public.spend_action(text,jsonb)'::regprocedure) INTO d; d:=replace(d,'p.status=''active'' AND (r=''finance'' OR p.created_by=auth.uid())','public.spend_project_allowed(p.id)'); EXECUTE d; END $$;